CREATE TYPE "LmsContentStatus" AS ENUM ('DRAFT','PUBLISHED','ARCHIVED');
ALTER TABLE "Lesson" ADD COLUMN "description" TEXT,ADD COLUMN "notes" TEXT,ADD COLUMN "branchId" TEXT,ADD COLUMN "courseId" TEXT,ADD COLUMN "batchId" TEXT,ADD COLUMN "subjectId" TEXT,ADD COLUMN "teacherId" TEXT,ADD COLUMN "chapter" TEXT,ADD COLUMN "homeworkId" TEXT,ADD COLUMN "testId" TEXT,ADD COLUMN "status" "LmsContentStatus" NOT NULL DEFAULT 'DRAFT',ADD COLUMN "videoName" TEXT,ADD COLUMN "videoMime" TEXT,ADD COLUMN "videoSize" INTEGER,ADD COLUMN "videoData" BYTEA;
ALTER TABLE "LessonProgress" ADD COLUMN "watchPercentage" INTEGER NOT NULL DEFAULT 0,ADD COLUMN "lastPositionSeconds" INTEGER NOT NULL DEFAULT 0,ADD COLUMN "timeSpentSeconds" INTEGER NOT NULL DEFAULT 0,ADD COLUMN "quizScore" DECIMAL(6,2),ADD COLUMN "assignmentStatus" TEXT,ADD COLUMN "completedAt" TIMESTAMP(3);
