CREATE UNIQUE INDEX "Lesson_batchId_subjectId_chapter_title_key" ON "Lesson"("batchId","subjectId","chapter","title");CREATE INDEX "Lesson_branchId_idx" ON "Lesson"("branchId");CREATE INDEX "Lesson_courseId_idx" ON "Lesson"("courseId");CREATE INDEX "Lesson_batchId_subjectId_idx" ON "Lesson"("batchId","subjectId");CREATE INDEX "Lesson_teacherId_idx" ON "Lesson"("teacherId");CREATE INDEX "Lesson_status_idx" ON "Lesson"("status");CREATE INDEX "LessonAttachment_lessonId_idx" ON "LessonAttachment"("lessonId");
ALTER TABLE "Lesson" ADD CONSTRAINT "Lesson_branchId_fkey" FOREIGN KEY("branchId") REFERENCES "Branch"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "Lesson" ADD CONSTRAINT "Lesson_courseId_fkey" FOREIGN KEY("courseId") REFERENCES "Course"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "Lesson" ADD CONSTRAINT "Lesson_batchId_fkey" FOREIGN KEY("batchId") REFERENCES "Batch"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "Lesson" ADD CONSTRAINT "Lesson_subjectId_fkey" FOREIGN KEY("subjectId") REFERENCES "Subject"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "Lesson" ADD CONSTRAINT "Lesson_teacherId_fkey" FOREIGN KEY("teacherId") REFERENCES "TeacherProfile"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "Lesson" ADD CONSTRAINT "Lesson_homeworkId_fkey" FOREIGN KEY("homeworkId") REFERENCES "Homework"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "Lesson" ADD CONSTRAINT "Lesson_testId_fkey" FOREIGN KEY("testId") REFERENCES "Test"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "LessonAttachment" ADD CONSTRAINT "LessonAttachment_lessonId_fkey" FOREIGN KEY("lessonId") REFERENCES "Lesson"("id") ON DELETE CASCADE ON UPDATE CASCADE;
